// Rocq: Relatives.relatives_implem.divout (local: divout)
// Variant: uncurried, lifted
pub fn divout(p: u64, m: u64, _H: ()) -> u64 {
  let tmp = eqb(mod_(m, p), 0u64);
  let tmp_1 = andb(ltb(0u64, m), ltb(1u64, p));
  let tmp_2 = andb(tmp, tmp_1);
  match bdec(tmp_2) {
    sumbool::left => {
      let tmp_3 = div(m, p);
      divout(p, tmp_3, ())
    },
    sumbool::right => {
      m
    },
  }
}

